window.__PAGES=window.__PAGES||{};window.__PAGES["pages/leads.html"]="<!-- Leads (Prospek) — Sales Module with Dynamic Pipeline Config -->\n<style>\n.leads-toolbar{display:flex;align-items:center;gap:12px;padding:18px 24px 0;flex-wrap:wrap}\n.leads-toolbar h1{font-size:20px;font-weight:700;flex:1}\n.view-toggle{display:flex;gap:0;border:1px solid var(--border);border-radius:8px;overflow:hidden}\n.view-toggle button{padding:6px 16px;font-size:13px;border:none;background:var(--card);cursor:pointer;color:var(--muted);border-right:1px solid var(--border)}\n.view-toggle button:last-child{border-right:none}\n.view-toggle button.active{background:var(--accent);color:#fff}\n.board-container{display:flex;gap:12px;padding:16px 24px;overflow-x:auto;flex:1;align-items:flex-start}\n.board-col{min-width:230px;max-width:230px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);display:flex;flex-direction:column;max-height:calc(100vh - 220px)}\n.board-col-header{padding:10px 12px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;position:sticky;top:0;background:var(--card);z-index:1;border-radius:var(--radius) var(--radius) 0 0}\n.board-col-header .stage-name{font-size:13px;font-weight:600}\n.board-col-header .count{background:var(--bg);border-radius:10px;padding:1px 8px;font-size:11px;color:var(--muted)}\n.board-col-body{padding:8px;display:flex;flex-direction:column;gap:6px;min-height:60px;overflow-y:auto;flex:1}\n.board-card{background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:10px;cursor:grab;transition:.15s;border-left:3px solid var(--accent);user-select:none}\n.board-card:active{cursor:grabbing}\n.board-card.dragging{opacity:.4;transform:scale(.96)}\n.board-col-body.drag-target{background:rgba(79,70,229,.04);border-radius:6px}\n.board-card:hover{box-shadow:var(--shadow);border-color:var(--accent)}\n.board-card .bc-title{font-size:13px;font-weight:600;color:var(--ink);margin-bottom:4px}\n.board-card .bc-contact{font-size:11px;color:var(--muted);margin-bottom:6px}\n.board-card .bc-meta{display:flex;justify-content:space-between;align-items:center}\n.board-card .bc-amount{font-size:12px;font-weight:600;color:var(--ok);background:#dcfce7;padding:1px 6px;border-radius:4px}\n.board-card .bc-avatar{width:22px;height:22px;border-radius:50%;background:var(--accent);display:grid;place-items:center;font-size:9px;font-weight:700;color:#fff}\n.board-card .bc-tag{font-size:10px;padding:1px 5px;border-radius:3px;display:inline-block;margin-top:4px}\n.tag-hot{background:#fef2f2;color:#dc2626}.tag-warm{background:#fef9c3;color:#a16207}.tag-cold{background:#eff6ff;color:#2563eb}.tag-enterprise{background:#f5f3ff;color:#7c3aed}\n.board-card .bc-seg{font-size:10px;padding:1px 5px;border-radius:3px;background:var(--bg);border:1px solid var(--border);display:inline-block;margin-top:4px;margin-left:3px}\n.board-card .bc-next{font-size:10px;color:var(--warn);margin-top:3px}\n.board-card .bc-visit{font-size:10px;color:var(--ok);margin-top:3px}\n.board-card.no-contact{border-left-color:var(--muted)}\n.leads-table-wrap{padding:0 24px 24px;overflow-x:auto}\n.leads-summary{display:flex;flex-wrap:wrap;gap:16px;padding:12px 24px}\n.leads-summary .stat{flex:1;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:12px 16px}\n.leads-summary .stat .val{font-size:22px;font-weight:700;color:var(--ink)}\n.leads-summary .stat .lbl{font-size:11px;color:var(--muted)}\n.leads-summary .stat.clickable{cursor:pointer}\n.leads-summary .stat.clickable:hover{border-color:var(--accent)}\n.leads-summary .stat.active{border-color:var(--warn);background:color-mix(in srgb,var(--warn) 8%,var(--card))}\n.leads-summary .stat .caret{font-size:10px;color:var(--muted);margin-left:4px}\n.pv-breakdown{width:100%;margin-top:10px}\n.pv-bar{display:flex;height:10px;border-radius:5px;overflow:hidden;background:var(--border)}\n.pv-bar .seg{cursor:pointer;transition:opacity .1s}\n.pv-bar .seg:hover{opacity:.75}\n.pv-legend{display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:8px}\n.pv-legend .item{cursor:pointer;font-size:11px;display:flex;align-items:center;gap:5px}\n.pv-legend .dot{width:8px;height:8px;border-radius:2px;flex:0 0 8px}\n.pv-legend .item .v{color:var(--muted)}\n.lead-detail-modal{position:fixed;inset:0;background:rgba(0,0,0,.4);display:none;place-items:start center;z-index:100;padding:40px 0;overflow-y:auto}\n.lead-detail-modal.open{display:grid}\n.lead-detail{background:var(--card);border-radius:14px;width:900px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.2);overflow:hidden}\n.ld-header{display:flex;align-items:center;gap:10px;padding:14px 20px;border-bottom:1px solid var(--border);background:var(--bg)}\n.ld-header .back{font-size:18px;cursor:pointer;color:var(--muted);padding:4px}.ld-header .back:hover{color:var(--ink)}\n.ld-breadcrumb{font-size:12px;color:var(--muted)}.ld-breadcrumb span{color:var(--accent);font-weight:500}\n.ld-body{display:grid;grid-template-columns:1fr 280px;min-height:500px}\n.ld-main{padding:20px;overflow-y:auto;max-height:70vh}\n.ld-sidebar{background:var(--bg);border-left:1px solid var(--border);padding:16px;overflow-y:auto;max-height:70vh}\n.ld-summary{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:16px}\n.ld-summary-top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}\n.ld-summary-title{font-size:18px;font-weight:700}\n.ld-summary-sub{font-size:12px;color:var(--muted);margin-top:2px}\n.ld-summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}\n.ld-summary-item .lbl{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.3px}\n.ld-summary-item .val{font-size:13px;font-weight:600;margin-top:2px;display:flex;min-width:0}\n.ld-summary-item .val .field-input{width:100%;text-align:left}\n.ld-summary-item .val.green{color:var(--ok)}.ld-summary-item .val.yellow{color:var(--warn)}\n.ld-pipeline{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:14px;margin-bottom:12px}\n.ld-pipeline-track{display:flex;gap:3px;margin:8px 0}\n.ld-pipeline-step{flex:1;height:6px;border-radius:3px;background:var(--border)}\n.ld-pipeline-step.done{background:var(--accent)}\n.ld-pipeline-step.current{background:var(--accent);box-shadow:0 0 6px var(--accent)}\n.ld-pipeline-labels{display:flex;justify-content:space-between}\n.ld-pipeline-labels span{font-size:9px;color:var(--muted)}\n.ld-pipeline-labels span.active{color:var(--accent);font-weight:700}\n.ld-guard-note{font-size:11px;color:var(--warn);margin-top:8px;padding:6px 10px;background:#fef9c3;border-radius:6px;border-left:3px solid var(--warn)}\n.ld-section{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);margin-bottom:8px;overflow:hidden}\n.ld-section-header{padding:10px 14px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;font-size:13px;font-weight:600}\n.ld-section-header:hover{background:var(--bg)}\n.ld-section-body{padding:0 14px 12px}\n.field-row{display:flex;align-items:center;gap:10px;padding:6px 0;font-size:13px}\n.field-row .lbl{color:var(--muted);flex:0 0 90px;font-size:12px}\n.field-row .val{color:var(--ink);text-align:right}\n.field-row .field-cell{flex:1;justify-content:stretch}\n.field-row .field-input{width:100%;text-align:left;background:var(--bg);border-color:var(--border)}\n.contact-new{font-size:12px;color:var(--muted);padding:4px 0 6px}\n.contact-new .link-btn{background:none;border:none;color:var(--accent);cursor:pointer;font-size:12px;text-decoration:underline;padding:0}\n.cl-title{font-size:18px;font-weight:700;color:var(--ink);border:1px solid transparent;border-radius:6px;padding:2px 6px;width:100%;background:var(--bg)}\n.cl-title:focus{border-color:var(--accent);outline:none}\n.cl-in{width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--ink);font-size:13px}\n.cl-in:focus{border-color:var(--accent);outline:none}\n.cl-error{color:var(--danger);font-size:12px;margin:8px 0}\n.cl-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}\n.cl-variant{margin-left:auto;display:flex;gap:2px;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:2px}\n.cl-variant button{width:26px;height:24px;border:none;background:none;color:var(--muted);font-size:12px;font-weight:700;border-radius:4px;cursor:pointer}\n.cl-variant button.active{background:var(--accent);color:#fff}\n.cl-lbl{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted)}\n.cl-2col{display:flex;gap:10px}\n.cl-2col .cl-lbl{flex:1}\n.cl-stepper-wrap{margin-top:4px}\n.cl-stepper-wrap .ld-pipeline-track{gap:4px;margin:4px 0 6px}\n.cl-step{flex:1;height:20px;border-radius:5px;background:var(--border);cursor:pointer;transition:background .12s}\n.cl-step:hover{opacity:.85}\n.cl-step.done,.cl-step.current{background:var(--accent)}\n.cl-step.current{box-shadow:0 0 6px var(--accent)}\n.cl-step-hint{font-size:10px;color:var(--muted);margin-top:2px}\n.ld-header{display:flex;align-items:center;gap:10px}\n.ld-delete{margin-left:auto;color:var(--danger);border-color:var(--danger)}\n.field-input{border:1px solid transparent;border-radius:4px;padding:2px 6px;font-size:13px;text-align:right;background:transparent;color:var(--ink);flex:1;min-width:0;transition:.15s;cursor:default}\n.field-input[readonly]{pointer-events:none}\n.field-cell{position:relative;display:inline-flex;align-items:center;justify-content:flex-end;flex:1;min-width:0;cursor:pointer;gap:4px}\n.field-cell:hover .field-input:not(.editing){border-color:var(--border);background:var(--card)}\n.field-cell:hover .edit-hint{opacity:1}\n.field-input.editing{pointer-events:auto;cursor:text;border-color:var(--accent);background:var(--card);box-shadow:0 0 0 2px rgba(79,70,229,.1)}\n.field-input:focus{border-color:var(--accent);outline:none;background:var(--card);box-shadow:0 0 0 2px rgba(79,70,229,.1)}\n.edit-hint{position:absolute;bottom:100%;right:0;margin-bottom:4px;background:var(--ink);color:var(--card);font-size:10px;padding:3px 8px;border-radius:4px;white-space:nowrap;opacity:0;transition:opacity .15s;pointer-events:none;z-index:5}\n.edit-hint::after{content:'';position:absolute;top:100%;right:12px;border:4px solid transparent;border-top-color:var(--ink)}\ntextarea.field-input{text-align:left;width:100%;min-height:60px;resize:vertical}\nselect.field-input{text-align:left;cursor:pointer;appearance:auto;text-overflow:ellipsis;overflow:hidden;white-space:nowrap;padding-right:20px}\n.tl-item{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid var(--bg)}\n.tl-item:last-child{border-bottom:none}\n.tl-icon{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:12px;flex-shrink:0}\n.tl-icon.status{background:#dbeafe}.tl-icon.comment{background:#ede9fe}.tl-icon.visit{background:#dcfce7}.tl-icon.activity{background:#fef3c7}.tl-icon.created{background:var(--bg);border:1px solid var(--border)}\n.tl-body{flex:1}.tl-title{font-size:12px;line-height:1.4}.tl-title strong{font-weight:600}\n.tl-detail{font-size:11px;color:var(--muted);margin-top:2px}.tl-time{font-size:10px;color:#9ca3af;margin-top:2px}\n.qa-btn{display:flex;align-items:center;gap:8px;padding:8px 12px;background:var(--card);border:1px solid var(--border);border-radius:8px;font-size:13px;cursor:pointer;margin-bottom:6px;width:100%}\n.qa-btn:hover{border-color:var(--accent);background:var(--bg)}\n.qa-form{border:1px solid var(--border);border-radius:8px;padding:10px;margin:0 0 6px;background:var(--card);display:none}\n.qa-form.open{display:block}\n.qa-form label{display:block;font-size:11px;color:var(--muted);margin:6px 0 3px}\n.qa-form label:first-child{margin-top:0}\n.qa-form input,.qa-form select,.qa-form textarea{width:100%;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:6px 8px;font-size:12px;box-sizing:border-box}\n.qa-form textarea{height:44px;resize:none}\n.qa-form .row{display:flex;gap:8px;margin-top:8px;justify-content:flex-end}\n.qa-form .row button{font-size:12px;padding:5px 12px;border-radius:6px;cursor:pointer;border:1px solid var(--border);background:var(--bg)}\n.qa-form .row button.primary{background:var(--accent);color:#fff;border-color:var(--accent)}\n.transition-popover{position:fixed;inset:0;background:rgba(0,0,0,.4);display:none;place-items:center;z-index:200}\n.transition-popover.open{display:grid}\n.transition-panel{background:var(--card);border-radius:14px;width:420px;box-shadow:0 20px 60px rgba(0,0,0,.25);overflow:hidden}\n.tp-header{padding:14px 18px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}\n.tp-header h3{font-size:15px;font-weight:600}\n.tp-section{padding:10px 18px}\n.tp-section-label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;display:flex;align-items:center;gap:8px}\n.tp-section-label .line{flex:1;height:1px;background:var(--border)}\n.tp-option{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-radius:8px;margin-bottom:4px;cursor:pointer;border:1px solid var(--border);transition:.1s}\n.tp-option:hover{background:var(--bg)}\n.tp-option.forward{border-left:3px solid var(--accent)}\n.tp-option.terminal{border-left:3px solid var(--danger);background:#fef2f2}\n.tp-option.terminal:hover{background:#fee2e2}\n.tp-option.locked{opacity:.35;cursor:not-allowed;border-left:3px solid var(--border)}\n.tp-opt-left{display:flex;align-items:center;gap:8px}\n.tp-opt-dot{width:10px;height:10px;border-radius:50%}\n.tp-opt-name{font-size:13px;font-weight:500}\n.tp-opt-badge{font-size:10px;padding:2px 6px;border-radius:4px}\n.badge-next{background:#dbeafe;color:#2563eb}.badge-terminal{background:#fef2f2;color:#dc2626}.badge-locked{background:var(--bg);color:var(--muted)}\n.tp-confirm{padding:14px 18px;background:#fefce8;border-top:1px solid var(--border)}\n.tp-confirm-title{font-size:13px;font-weight:600;color:var(--warn);margin-bottom:8px}\n.tp-confirm label{display:block;font-size:12px;color:var(--muted);margin-bottom:4px}\n.tp-confirm select,.tp-confirm textarea{width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;font-size:13px;background:var(--card);margin-bottom:8px}\n.tp-confirm textarea{height:50px;resize:none}\n.tp-actions{display:flex;gap:8px;justify-content:flex-end;padding:0 18px 16px}\n.visit-pill{display:inline-flex;align-items:center;gap:6px;background:var(--card);border:1px solid var(--border);border-radius:20px;padding:5px 12px;font-size:13px;font-weight:500;color:var(--ink);cursor:pointer;transition:.15s}\n.visit-pill:hover{border-color:var(--accent);background:var(--bg)}\n.visit-count{background:var(--danger);color:#fff;font-size:11px;font-weight:700;min-width:18px;height:18px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;padding:0 5px}\n.visit-count.zero{background:var(--muted)}\n.vm-overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);display:none;place-items:center;z-index:120}\n.vm-overlay.open{display:grid}\n.vm-panel{background:var(--card);border-radius:14px;width:75vw;height:75vh;max-width:1100px;box-shadow:0 20px 60px rgba(0,0,0,.25);display:flex;flex-direction:column;overflow:hidden}\n.vm-head{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border);flex-shrink:0}\n.vm-head h2{font-size:17px;font-weight:700}\n.vm-close{cursor:pointer;font-size:20px;color:var(--muted);background:none;border:none;line-height:1}\n.vm-close:hover{color:var(--ink)}\n.vm-body{flex:1;overflow-y:auto}\n\n/* ============================================================\n   4 LAYOUT VARIAN — switch dari main nav (rail 🎨). Class di #app.\n   Semua reuse elemen toolbar/summary/filter yg sama; hanya reflow CSS.\n   ponytail: tanpa render JS baru — cukup body-class + CSS + 1 FAB markup.\n   ============================================================ */\n/* FAB (dipakai varian B & D) — default sembunyi */\n#leadsFab{display:none;position:fixed;right:20px;bottom:20px;width:56px;height:56px;border-radius:50%;\n  background:var(--accent);color:#fff;font-size:28px;border:none;box-shadow:0 6px 20px rgba(79,70,229,.45);\n  cursor:pointer;z-index:50;align-items:center;justify-content:center}\n#leadsFab:hover{background:var(--accent-hover)}\n\n/* ---------- A · Grouped + Quiet State ---------- */\n/* active filter jadi tint lembut (bukan solid), create tetap CTA solid; grup dipisah spacing */\n#app.layout-a .filter-chip.active{background:var(--accent-soft,#eef2ff);color:var(--accent);border-color:var(--accent)}\n#app.layout-a .leads-toolbar{padding-bottom:6px}\n#app.layout-a #leadsFilterBar{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;margin-top:4px;order:9;flex-basis:100%}\n#app.layout-a #leadsFilterBar::-webkit-scrollbar{display:none}\n\n/* ---------- B · FAB + KPI Carousel ---------- */\n/* create inline → FAB; view-toggle hidden (paksa board); KPI 1-baris scroll semua width */\n#app.layout-b .view-toggle{display:none}\n#app.layout-b .leads-toolbar > .btn.primary{display:none}\n#app.layout-b #leadsFab{display:flex}\n#app.layout-b .leads-summary{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}\n#app.layout-b .leads-summary::-webkit-scrollbar{display:none}\n#app.layout-b .leads-summary .stat{flex:0 0 200px}\n#app.layout-b #leadsFilterBar{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;flex-basis:100%;order:9;margin-top:4px}\n#app.layout-b #leadsFilterBar::-webkit-scrollbar{display:none}\n#app.layout-b .filter-chip.active{background:var(--accent-soft,#eef2ff);color:var(--accent);border-color:var(--accent)}\n\n/* ---------- C · Tab Underline ---------- */\n/* filter chip → tab underline (beda bentuk dari tombol → hierarki jelas); view-toggle hidden */\n#app.layout-c .view-toggle{display:none}\n#app.layout-c .leads-summary .stat .val{font-size:18px}\n#app.layout-c #leadsFilterBar{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;gap:2px;flex-basis:100%;order:9;\n  border-bottom:1px solid var(--border);padding-bottom:0;margin-top:6px}\n#app.layout-c #leadsFilterBar::-webkit-scrollbar{display:none}\n#app.layout-c .filter-chip{border:none!important;border-radius:0!important;background:none!important;color:var(--muted)!important;\n  padding:9px 12px!important;border-bottom:2px solid transparent!important;white-space:nowrap;font-weight:600}\n#app.layout-c .filter-chip.active{color:var(--accent)!important;border-bottom-color:var(--accent)!important}\n\n/* ---------- D · Compact + FAB ---------- */\n/* rapetin toolbar, KPI ringkas, create → FAB, view-toggle hidden, board card padat */\n#app.layout-d .view-toggle{display:none}\n#app.layout-d .board-card{padding:7px 9px}\n#app.layout-d .board-card .bc-contact{margin-bottom:3px}\n#app.layout-d .leads-toolbar{padding-top:12px;padding-bottom:4px;gap:8px}\n#app.layout-d .leads-toolbar h1{font-size:18px}\n#app.layout-d .leads-toolbar > .btn.primary{display:none}\n#app.layout-d #leadsFab{display:flex}\n#app.layout-d .leads-summary{gap:8px;padding-top:6px;padding-bottom:6px}\n#app.layout-d .leads-summary .stat{padding:8px 12px}\n#app.layout-d .leads-summary .stat .val{font-size:17px}\n#app.layout-d #leadsFilterBar{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;flex-basis:100%;order:9;margin-top:2px}\n#app.layout-d #leadsFilterBar::-webkit-scrollbar{display:none}\n#app.layout-d .filter-chip.active{background:var(--accent-soft,#eef2ff);color:var(--accent);border-color:var(--accent)}\n</style>\n\n<div class=\"leads-toolbar\">\n  <h1>💰 Prospek</h1>\n  <button class=\"visit-pill\" onclick=\"openVisitModal()\" title=\"Kunjungan menunggu approval\">\n    📍 Kunjungan<span class=\"visit-count\" id=\"visitApprovalCount\">0</span>\n  </button>\n  <div class=\"view-toggle\">\n    <button id=\"vtBoard\" class=\"active\" onclick=\"setLeadsView('board')\">📊 Board</button>\n    <button id=\"vtTable\" onclick=\"setLeadsView('table')\">📋 Table</button>\n  </div>\n  <div class=\"page-filters\" style=\"padding:0;border:none\" id=\"leadsFilterBar\"></div>\n  <button class=\"btn\" id=\"sortBtn\" onclick=\"toggleSortDir()\">↕ Tanggal</button>\n  <button class=\"btn primary\" onclick=\"openCreateLead()\">＋ Prospek Baru</button>\n</div>\n<div class=\"leads-summary\" id=\"leadsSummary\"></div>\n<div class=\"vm-overlay\" id=\"visitModal\" onclick=\"if(event.target===this)closeVisitModal()\">\n  <div class=\"vm-panel\">\n    <div class=\"vm-head\"><h2>📍 Kunjungan — Approval</h2><button class=\"vm-close\" onclick=\"closeVisitModal()\">✕</button></div>\n    <div class=\"vm-body\" id=\"visitModalBody\"></div>\n  </div>\n</div>\n<div class=\"lead-detail-modal\" id=\"createLeadModal\" onclick=\"if(event.target===this)closeCreateLead()\">\n  <div class=\"lead-detail\" style=\"width:640px\">\n    <div class=\"ld-header\">\n      <span class=\"back\" onclick=\"closeCreateLead()\">←</span>\n      <div class=\"ld-breadcrumb\">Sales / <a onclick=\"closeCreateLead()\">Leads</a> / <span>Prospek Baru</span></div>\n      <div class=\"cl-variant\" id=\"clVariant\">\n        <button data-v=\"a\" onclick=\"setCreateVariant('a')\" title=\"Tampilan detail\">A</button>\n        <button data-v=\"b\" onclick=\"setCreateVariant('b')\" title=\"Tampilan ringkas\">B</button>\n        <button data-v=\"c\" onclick=\"setCreateVariant('c')\" title=\"Form sederhana\">C</button>\n      </div>\n    </div>\n    <div id=\"clBody\"></div>\n  </div>\n</div>\n<div class=\"board-container\" id=\"leadsBoard\"></div>\n<button id=\"leadsFab\" onclick=\"openCreateLead()\" title=\"Prospek Baru\" aria-label=\"Prospek Baru\">＋</button>\n<div class=\"leads-table-wrap hide\" id=\"leadsTableWrap\">\n  <table class=\"data-table\" id=\"leadsTable\">\n    <thead><tr><th>Judul Lead</th><th>Nama PIC</th><th>Segment</th><th>Status</th><th>Nilai</th><th>Assignee</th><th>Next Action</th></tr></thead>\n    <tbody id=\"leadsTableBody\"></tbody>\n  </table>\n</div>\n<div class=\"lead-detail-modal\" id=\"leadDetailModal\" onclick=\"if(event.target===this)closeLeadDetail()\">\n  <div class=\"lead-detail\" id=\"leadDetailContent\"></div>\n</div>\n<div class=\"transition-popover\" id=\"transitionPopover\" onclick=\"if(event.target===this)closeTransition()\">\n  <div class=\"transition-panel\" id=\"transitionPanel\"></div>\n</div>\n\n<script>\n// === DYNAMIC STAGES FROM SETTINGS ===\nfunction getStages(){ return DB.settings?.leadStages||[]; }\nfunction getSegments(){ return DB.settings?.leadSegments||[]; }\nfunction getTerminal(){ return getStages().filter(s=>s.isTerminal).map(s=>s.key); }\nfunction getForwardMap(){\n  const stages=getStages();\n  const terminal=getTerminal();\n  const map={};\n  stages.forEach((s,i)=>{\n    if(terminal.includes(s.key)){map[s.key]=[];return}\n    map[s.key]=stages.slice(i+1).map(x=>x.key);\n  });\n  return map;\n}\nfunction stageByKey(key){ return getStages().find(s=>s.key===key); }\nfunction stageIndex(key){ return getStages().findIndex(s=>s.key===key); }\n\nvar LOST_REASONS=['Budget tidak tersedia','Memilih kompetitor','Tidak ada kebutuhan','Tidak ada respon','Lainnya'];\nvar leadsView='board',leadFilter='all',editLeadId=null,detailLeadId=null,sortDir='desc',pvOpen=false;\n\n// === INLINE-EDIT FIELD BUILDERS ===\n// Field terkunci; hover kasih tooltip, double-click buka edit + fokus.\nvar _hint='<span class=\"edit-hint\">Klik 2x untuk edit</span>';\nfunction _cell(inner){return `<span class=\"field-cell\" ondblclick=\"unlockField(this)\">${inner}${_hint}</span>`;}\nfunction editInput(id,field,value,type){\n  type=type||'text';\n  return _cell(`<input class=\"field-input\" type=\"${type}\" value=\"${(value==null?'':String(value)).replace(/\"/g,'&quot;')}\" readonly onchange=\"saveLeadField('${id}','${field}',this.value)\" onblur=\"lockField(this)\">`);\n}\nfunction editSelect(id,field,value,options){\n  var opts=options.map(o=>`<option${o.v===value?' selected':''} value=\"${o.v}\">${o.t}</option>`).join('');\n  return `<span class=\"field-cell\"><select class=\"field-input\" onchange=\"saveLeadField('${id}','${field}',this.value);lockField(this)\" onblur=\"lockField(this)\">${opts}</select><span class=\"edit-hint\">Klik untuk ganti</span></span>`;\n}\nfunction editTextarea(id,field,value){\n  return `<span class=\"field-cell\" style=\"width:100%\" ondblclick=\"unlockField(this)\"><textarea class=\"field-input\" readonly onchange=\"saveLeadField('${id}','${field}',this.value)\" onblur=\"lockField(this)\">${value||''}</textarea>${_hint}</span>`;\n}\n// ponytail: input pakai 100ms delay biar single-click (buka detail) tidak nge-fokus;\n// select unlock sinkron biar dblclick yang sama langsung buka list (native select\n// tak bisa di-open programatik, jadi harus interaktif saat mousedown ke-2 mendarat)\nfunction unlockField(cell){\n  var f=cell.querySelector('.field-input');\n  if(f.tagName==='SELECT'){f.classList.add('editing');f.focus();return;}\n  setTimeout(function(){\n    f.classList.add('editing');\n    f.removeAttribute('readonly');\n    f.focus();\n    if(f.select)f.select();\n  },100);\n}\nfunction lockField(f){\n  f.classList.remove('editing');\n  if(f.tagName!=='SELECT')f.setAttribute('readonly','');\n}\n\n// === FILTER CHIPS (dynamic) ===\nfunction renderFilterBar(){\n  const stages=getStages();\n  const bar=document.getElementById('leadsFilterBar');\n  bar.innerHTML=`<span class=\"filter-chip ${leadFilter==='all'?'active':''}\" onclick=\"filterLeads(this,'all')\">Semua</span>`+\n    (leadFilter==='__followup'?`<span class=\"filter-chip active\" onclick=\"toggleFollowupFilter()\" style=\"border-color:var(--warn)\">📅 Butuh Follow-up ✕</span>`:'')+\n    stages.map(s=>`<span class=\"filter-chip ${leadFilter===s.key?'active':''}\" onclick=\"filterLeads(this,'${s.key}')\">${s.icon} ${s.label}</span>`).join('');\n}\n\n// === RENDER ===\n// ponytail: satu ambang follow-up dipakai KPI + filter (hindari 2 angka yang bisa beda).\nvar FOLLOWUP_DAYS=3;\nfunction isFollowup(l){return l.nextActionAt&&new Date(l.nextActionAt)<=new Date(Date.now()+FOLLOWUP_DAYS*864e5)}\nfunction matchLeadFilter(l){\n  if(leadFilter==='all')return true;\n  if(leadFilter==='__followup')return isFollowup(l);\n  return l.status===leadFilter;\n}\nfunction renderLeads(){\n  renderFilterBar();\n  renderSummary();\n  var n=(DB.visits||[]).filter(v=>v.status==='waiting_review').length;\n  var el=document.getElementById('visitApprovalCount');\n  if(el){el.textContent=n;el.classList.toggle('zero',n===0);}\n  if(leadsView==='board')renderBoard();else renderTable();\n}\n\nfunction renderSummary(){\n  const leads=DB.leads||[];\n  const terminal=getTerminal();\n  const stages=getStages();\n  const pipeline=leads.filter(l=>!terminal.includes(l.status)).reduce((s,l)=>s+(l.value||0),0);\n  const followup=leads.filter(isFollowup).length;\n  // ponytail: satu kartu clickable per stage terminal (Won/Lost/Closed) — preset-agnostic.\n  var termCards=stages.filter(s=>terminal.includes(s.key)).map(function(s){\n    var col=leads.filter(l=>l.status===s.key);\n    return {key:s.key,label:s.label,color:s.color,icon:s.icon,\n            val:col.reduce((t,l)=>t+(l.value||0),0),count:col.length};\n  });\n  // ponytail: pipeline value split by active (non-terminal) stage. data already here, no new field.\n  var pvStages=stages.filter(s=>!terminal.includes(s.key)).map(function(s){\n    var col=leads.filter(l=>l.status===s.key);\n    return {key:s.key,label:s.label,color:s.color,icon:s.icon,\n            val:col.reduce((t,l)=>t+(l.value||0),0),count:col.length};\n  });\n  var bd='';\n  if(pvOpen){\n    var bar=pvStages.map(s=>s.val<=0?'':`<div class=\"seg\" title=\"${s.label}: ${fmtRupiah(s.val)} (${s.count} lead)\" onclick=\"filterStage('${s.key}')\" style=\"flex:${s.val};background:${s.color}\"></div>`).join('');\n    var legend=pvStages.map(s=>`<div class=\"item\" onclick=\"filterStage('${s.key}')\"><span class=\"dot\" style=\"background:${s.color}\"></span>${s.icon} ${s.label} <span class=\"v\">${fmtRupiah(s.val)} · ${s.count}</span></div>`).join('');\n    bd=`<div class=\"pv-breakdown\"><div class=\"pv-bar\">${bar||'<div class=\"seg\" style=\"flex:1;background:var(--border)\"></div>'}</div><div class=\"pv-legend\">${legend}</div></div>`;\n  }\n  document.getElementById('leadsSummary').innerHTML=`\n    <div class=\"stat\"><div class=\"val\">${leads.length}</div><div class=\"lbl\">Total Leads</div></div>\n    <div class=\"stat clickable\" onclick=\"togglePvBreakdown()\"><div class=\"val\" style=\"color:var(--ok)\">${fmtRupiah(pipeline)}<span class=\"caret\">${pvOpen?'▲':'▼'}</span></div><div class=\"lbl\">Pipeline Value</div></div>\n    <div class=\"stat clickable${leadFilter==='__followup'?' active':''}\" onclick=\"toggleFollowupFilter()\"><div class=\"val\" style=\"color:var(--warn)\">${followup}</div><div class=\"lbl\">Butuh Follow-up${leadFilter==='__followup'?' · aktif ✕':''}</div></div>\n    ${termCards.map(s=>`<div class=\"stat clickable${leadFilter===s.key?' active':''}\" onclick=\"filterStage('${s.key}')\"><div class=\"val\" style=\"color:${s.color}\">${fmtRupiah(s.val)}</div><div class=\"lbl\">${s.icon} ${s.label} · ${s.count}${leadFilter===s.key?' ✕':''}</div></div>`).join('')}\n    ${bd}\n  `;\n}\nfunction togglePvBreakdown(){pvOpen=!pvOpen;renderSummary()}\nfunction filterStage(key){leadFilter=(leadFilter===key)?'all':key;renderLeads()}\nfunction toggleFollowupFilter(){leadFilter=(leadFilter==='__followup')?'all':'__followup';renderLeads()}\n\nfunction renderBoard(){\n  const wrap=document.getElementById('leadsBoard');\n  wrap.classList.remove('hide');\n  document.getElementById('leadsTableWrap').classList.add('hide');\n  const stages=getStages();\n  const leads=(DB.leads||[]).filter(matchLeadFilter).sort((a,b)=>sortDir==='desc'?new Date(b.createdAt)-new Date(a.createdAt):new Date(a.createdAt)-new Date(b.createdAt));\n  wrap.innerHTML=stages.map(s=>{\n    const col=leads.filter(l=>l.status===s.key);\n    return `<div class=\"board-col\">\n      <div class=\"board-col-header\">\n        <span class=\"stage-name\" style=\"color:${s.color}\">${s.icon} ${s.label}</span>\n        <span class=\"count\">${col.length}</span>\n      </div>\n      <div class=\"board-col-body\" data-stage=\"${s.key}\" ondragover=\"boardDragOver(event)\" ondragleave=\"boardDragLeave(event)\" ondrop=\"boardDrop(event,'${s.key}')\">${col.map(l=>renderBoardCard(l,s)).join('')||'<div style=\"text-align:center;color:var(--muted);font-size:12px;padding:20px\">Kosong</div>'}</div>\n    </div>`;\n  }).join('');\n}\n\nfunction renderBoardCard(l,stageObj){\n  const a=DB.agents.find(x=>x.id===l.assignee);\n  const seg=l.segment?`<span class=\"bc-seg\">${l.segment}</span>`:'';\n  const nextHtml=l.nextAction?`<div class=\"bc-next\">📅 ${l.nextAction}${l.nextActionAt?' · '+fmtDate(l.nextActionAt):''}</div>`:'';\n  // ponytail: visit belum-selesai (on_plan/waiting_review) -> badge di card. data dari DB.visits.\n  const vs=(DB.visits||[]).find(v=>v.leadId===l.id&&(v.status==='on_plan'||v.status==='waiting_review'));\n  const visitHtml=vs?`<div class=\"bc-visit\">📍 Visit ${vs.status==='waiting_review'?'menunggu review':fmtDate(vs.plannedAt)}</div>`:'';\n  return `<div class=\"board-card${l.contact?'':' no-contact'}\" style=\"border-left-color:${stageObj?.color||'var(--accent)'}\" draggable=\"true\" data-id=\"${l.id}\" ondragstart=\"boardDragStart(event,'${l.id}')\" ondragend=\"boardDragEnd(event)\" onclick=\"openLeadDetail('${l.id}')\">\n    <div class=\"bc-title\">${l.company}</div>\n    <div class=\"bc-contact\">${l.contact?'👤 '+l.contact:'⚠️ Tanpa kontak'}</div>\n    <div class=\"bc-meta\">\n      <span class=\"bc-amount\">${fmtRupiah(l.value||0)}</span>\n      <div class=\"bc-avatar\">${a?a.initials:'?'}</div>\n    </div>\n    ${seg}${nextHtml}${visitHtml}\n  </div>`;\n}\n\nfunction renderTable(){\n  document.getElementById('leadsBoard').classList.add('hide');\n  document.getElementById('leadsTableWrap').classList.remove('hide');\n  const stages=getStages();\n  const leads=(DB.leads||[]).filter(matchLeadFilter).sort((a,b)=>sortDir==='desc'?new Date(b.createdAt)-new Date(a.createdAt):new Date(a.createdAt)-new Date(b.createdAt));\n  document.getElementById('leadsTableBody').innerHTML=leads.map(l=>{\n    const a=DB.agents.find(x=>x.id===l.assignee);\n    const sObj=stageByKey(l.status);\n    return `<tr onclick=\"openLeadDetail('${l.id}')\" style=\"cursor:pointer\">\n      <td><strong>${l.company}</strong></td>\n      <td>${l.contact||'<span style=\"color:var(--muted)\">—</span>'}</td>\n      <td>${l.segment?`<span class=\"bc-seg\">${l.segment}</span>`:'—'}</td>\n      <td><span class=\"status\" style=\"background:${sObj?.color||'#888'}22;color:${sObj?.color||'#888'}\">${sObj?.label||l.status}</span></td>\n      <td style=\"font-weight:600\">${fmtRupiah(l.value||0)}</td>\n      <td>${a?a.name:'-'}</td>\n      <td style=\"font-size:12px;color:var(--warn)\">${l.nextAction||'—'}</td>\n    </tr>`;\n  }).join('')||'<tr><td colspan=\"7\" style=\"text-align:center;color:var(--muted);padding:32px\">Belum ada prospek</td></tr>';\n}\n\nfunction setLeadsView(v){leadsView=v;document.getElementById('vtBoard').classList.toggle('active',v==='board');document.getElementById('vtTable').classList.toggle('active',v==='table');renderLeads()}\nfunction filterLeads(el,status){document.querySelectorAll('#leadsFilterBar .filter-chip').forEach(c=>c.classList.remove('active'));el.classList.add('active');leadFilter=status;renderLeads()}\nfunction toggleSortDir(){sortDir=sortDir==='desc'?'asc':'desc';document.getElementById('sortBtn').textContent=sortDir==='desc'?'↓ Terbaru':'↑ Terlama';renderLeads()}\n\n// === DRAG & DROP ===\nvar dragLeadId=null;\nfunction boardDragStart(e,leadId){dragLeadId=leadId;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',leadId);e.target.classList.add('dragging')}\nfunction boardDragEnd(e){e.target.classList.remove('dragging');document.querySelectorAll('.drag-target').forEach(el=>el.classList.remove('drag-target'));dragLeadId=null}\nfunction boardDragOver(e){e.preventDefault();e.dataTransfer.dropEffect='move';e.currentTarget.classList.add('drag-target')}\nfunction boardDragLeave(e){e.currentTarget.classList.remove('drag-target')}\nfunction boardDrop(e,newStatus){\n  e.preventDefault();e.currentTarget.classList.remove('drag-target');\n  const leadId=e.dataTransfer.getData('text/plain')||dragLeadId;if(!leadId)return;\n  const l=dbFind('leads',leadId);if(!l||l.status===newStatus)return;\n  const terminal=getTerminal();\n  if(terminal.includes(newStatus)){openTransition(leadId);return}\n  const oldLabel=stageByKey(l.status)?.label;const newLabel=stageByKey(newStatus)?.label;\n  dbUpdate('leads',leadId,{status:newStatus});\n  dbAdd('leadActivities',{id:genId('la'),leadId,type:'status',actor:DB.currentUser?.id||'u1',text:`Status: ${oldLabel} → ${newLabel}`,detail:'Drag & drop',at:new Date().toISOString()});\n  renderLeads();showToast(`Status: ${l.company} → ${newLabel}`);\n}\n\n// === LEAD DETAIL ===\nfunction openLeadDetail(id){\n  detailLeadId=id;\n  const l=dbFind('leads',id);if(!l)return;\n  const a=DB.agents.find(x=>x.id===l.assignee);\n  const activities=(DB.leadActivities||[]).filter(ac=>ac.leadId===id).sort((a,b)=>new Date(b.at)-new Date(a.at));\n  const stages=getStages();\n  const sObj=stageByKey(l.status);\n  const sIdx=stageIndex(l.status);\n  const stageLabels=stages.map((s,i)=>`<span class=\"${i<sIdx?'active':''}\">${s.label}</span>`).join('');\n  const stageTrack=stages.map((s,i)=>`<div class=\"ld-pipeline-step ${i<sIdx?'done':i===sIdx?'current':''}\"></div>`).join('');\n  const terminal=getTerminal();\n  const terminalLabels=terminal.map(k=>stageByKey(k)?.label).join('/');\n  const tlIcon={status:'🔄',comment:'💬',visit:'📍',activity:'📅',created:'👤'};\n\n  document.getElementById('leadDetailContent').innerHTML=`\n    <div class=\"ld-header\">\n      <span class=\"back\" onclick=\"closeLeadDetail()\">←</span>\n      <div class=\"ld-breadcrumb\">Sales / <a onclick=\"closeLeadDetail()\">Leads</a> / <span>${l.company}</span></div>\n      ${canDelete()?`<button class=\"btn ld-delete\" onclick=\"deleteLead('${l.id}')\" title=\"Hapus prospek\">🗑 Hapus</button>`:''}\n    </div>\n    <div class=\"ld-body\">\n      <div class=\"ld-main\">\n        <div class=\"ld-summary\">\n          <div class=\"ld-summary-top\">\n            <div>\n              <div class=\"ld-summary-title\">${l.company}</div>\n              <div class=\"ld-summary-sub\">${l.contact||'Tanpa kontak'}${l.phone?' · '+l.phone:''} · Sumber: ${l.source}${l.segment?' · Segment: '+l.segment:''}</div>\n            </div>\n            <span class=\"status\" style=\"background:${sObj?.color||'#888'}22;color:${sObj?.color||'#888'};font-size:13px;padding:4px 12px\">${sObj?.icon||'•'} ${sObj?.label||l.status}</span>\n          </div>\n          <div class=\"ld-summary-grid\">\n            <div class=\"ld-summary-item\"><div class=\"lbl\">Amount</div><div class=\"val green\">${editInput(l.id,'value',l.value||0,'number')}</div></div>\n            <div class=\"ld-summary-item\"><div class=\"lbl\">Assignee</div><div class=\"val\">${editSelect(l.id,'assignee',l.assignee,DB.agents.map(ag=>({v:ag.id,t:ag.name})))}</div></div>\n            <div class=\"ld-summary-item\"><div class=\"lbl\">Next Action</div><div class=\"val yellow\">${editInput(l.id,'nextAction',l.nextAction||'','text')}</div></div>\n            <div class=\"ld-summary-item\"><div class=\"lbl\">Next Date</div><div class=\"val\">${editInput(l.id,'nextActionAt',l.nextActionAt?l.nextActionAt.substring(0,10):'','date')}</div></div>\n          </div>\n        </div>\n        <div class=\"ld-pipeline\">\n          <div style=\"font-size:12px;font-weight:600;color:var(--muted);margin-bottom:4px\">📍 Status Pipeline</div>\n          <div class=\"ld-pipeline-track\">${stageTrack}</div>\n          <div class=\"ld-pipeline-labels\">${stageLabels}</div>\n          <div class=\"ld-guard-note\">⚠️ Transisi ke <b>${terminalLabels}</b> memerlukan alasan. Kembali dari terminal butuh approval Supervisor.</div>\n        </div>\n        <div class=\"ld-section\">\n          <div class=\"ld-section-header\" onclick=\"this.nextElementSibling.classList.toggle('hide')\">👤 Informasi Kontak <span style=\"color:var(--muted)\">▼</span></div>\n          <div class=\"ld-section-body\">\n            <div class=\"field-row\"><span class=\"lbl\">Nama PIC</span>${contactField(l.id,'contact',l.contact||'')}</div>\n            <div class=\"field-row\"><span class=\"lbl\">Telepon</span>${contactField(l.id,'phone',l.phone||'')}</div>\n            <div class=\"field-row\"><span class=\"lbl\">Email</span>${contactField(l.id,'email',l.email||'')}</div>\n            <div class=\"field-row\"><span class=\"lbl\">Judul Lead</span>${editInput(l.id,'company',l.company,'text')}</div>\n            <div id=\"ldContactSuggest\"></div>\n            ${contactDatalist()}\n            <div class=\"field-row\"><span class=\"lbl\">Sumber</span>${editSelect(l.id,'source',l.source,['WhatsApp','Widget','Broadcast','Referral'].map(s=>({v:s,t:s})))}</div>\n            <div class=\"field-row\"><span class=\"lbl\">Segment</span>${editSelect(l.id,'segment',l.segment||'',[{v:'',t:'— Tanpa segment —'}].concat(getSegments().map(s=>({v:s,t:s}))))}</div>\n          </div>\n        </div>\n        <div class=\"ld-section\">\n          <div class=\"ld-section-header\" onclick=\"this.nextElementSibling.classList.toggle('hide')\">📝 Deskripsi <span style=\"color:var(--muted)\">▼</span></div>\n          <div class=\"ld-section-body\">${editTextarea(l.id,'description',l.description||'')}</div>\n        </div>\n        <div class=\"ld-section\">\n          <div class=\"ld-section-header\" onclick=\"this.nextElementSibling.classList.toggle('hide')\">📋 Activity Timeline (${activities.length}) <span style=\"color:var(--muted)\">▼</span></div>\n          <div class=\"ld-section-body\">\n            ${activities.length?activities.map(ac=>{const actor=DB.agents.find(x=>x.id===ac.actor);return `<div class=\"tl-item\"><div class=\"tl-icon ${ac.type}\">${tlIcon[ac.type]||'•'}</div><div class=\"tl-body\"><div class=\"tl-title\"><strong>${ac.actor==='system'?'System':actor?actor.name:'Unknown'}</strong> ${ac.text}</div>${ac.detail?`<div class=\"tl-detail\">${ac.detail}</div>`:''}<div class=\"tl-time\">${fmtDate(ac.at)} · ${fmtTime(ac.at)}</div></div></div>`}).join(''):'<div style=\"text-align:center;color:var(--muted);font-size:13px;padding:20px\">Belum ada aktivitas</div>'}\n          </div>\n        </div>\n      </div>\n      <div class=\"ld-sidebar\">\n        <div style=\"font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase;margin-bottom:10px\">⚡ Quick Actions</div>\n        <button class=\"qa-btn\" onclick=\"openTransition('${l.id}')\">🔄 Ubah Status</button>\n        <button class=\"qa-btn\" onclick=\"toggleQaForm('qaActivity')\">📅 Jadwalkan Aktivitas</button>\n        <div class=\"qa-form\" id=\"qaActivity\">\n          <label>Jenis</label>\n          <select id=\"qaActType\"><option value=\"Telepon\">📞 Telepon</option><option value=\"Meeting\">🤝 Meeting</option><option value=\"WhatsApp\">💬 WhatsApp</option><option value=\"Email\">✉️ Email</option></select>\n          <label>Tanggal</label>\n          <input type=\"date\" id=\"qaActDate\" value=\"${new Date().toISOString().slice(0,10)}\">\n          <label>Catatan</label>\n          <textarea id=\"qaActNote\" placeholder=\"Opsional...\"></textarea>\n          <div class=\"row\"><button onclick=\"toggleQaForm('qaActivity')\">Batal</button><button class=\"primary\" onclick=\"saveActivity('${l.id}')\">Simpan</button></div>\n        </div>\n        <button class=\"qa-btn\" onclick=\"toggleQaForm('qaVisit')\">📍 Buat Visit</button>\n        <div class=\"qa-form\" id=\"qaVisit\">\n          <label>Tanggal &amp; jam</label>\n          <input type=\"datetime-local\" id=\"qaVisDate\" value=\"${new Date(Date.now()+864e5).toISOString().slice(0,16)}\">\n          <label>Lokasi</label>\n          <input type=\"text\" id=\"qaVisLoc\" placeholder=\"Kantor / alamat kunjungan\">\n          <label>Tujuan</label>\n          <textarea id=\"qaVisNote\" placeholder=\"Mis. presentasi proposal\"></textarea>\n          <div class=\"row\"><button onclick=\"toggleQaForm('qaVisit')\">Batal</button><button class=\"primary\" onclick=\"saveVisit('${l.id}')\">Buat</button></div>\n        </div>\n        <div style=\"border-top:1px solid var(--border);margin:16px 0\"></div>\n        <div style=\"font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase;margin-bottom:8px\">💬 Komentar</div>\n        <textarea id=\"ldCommentInput\" placeholder=\"Tulis komentar...\" style=\"width:100%;background:var(--card);border:1px solid var(--border);border-radius:6px;padding:8px;font-size:13px;height:60px;resize:none\"></textarea>\n        <button class=\"btn primary\" style=\"margin-top:6px;float:right;font-size:12px\" onclick=\"addLeadComment('${l.id}')\">Kirim</button>\n        <div style=\"clear:both;border-top:1px solid var(--border);margin:16px 0\"></div>\n        <div style=\"font-size:12px;font-weight:600;color:var(--muted);text-transform:uppercase;margin-bottom:8px\">📊 Ringkasan</div>\n        <div style=\"font-size:13px;color:var(--muted);line-height:1.8\">\n          <div>Days in stage: <strong style=\"color:var(--ink)\">${Math.max(1,Math.floor((Date.now()-new Date(l.createdAt))/864e5))} hari</strong></div>\n          ${terminal.includes(l.status)?`<div style=\"color:var(--ok);margin-top:4px\">🏆 ${sObj?.label||'Closed'} · ${fmtDate(l.wonAt||l.lostAt||l.closedAt)}</div>`:''}\n          ${l.lostReason?`<div style=\"color:var(--danger);margin-top:4px\">❌ ${l.lostReason}</div>`:''}\n        </div>\n      </div>\n    </div>`;\n  document.getElementById('leadDetailModal').classList.add('open');\n  renderContactSuggest(id);\n}\nfunction closeLeadDetail(){document.getElementById('leadDetailModal').classList.remove('open');detailLeadId=null}\nfunction addLeadComment(id){const input=document.getElementById('ldCommentInput');const text=input.value.trim();if(!text)return;dbAdd('leadActivities',{id:genId('la'),leadId:id,type:'comment',actor:DB.currentUser?.id||'u1',text:'Menambahkan komentar',detail:'\"'+text+'\"',at:new Date().toISOString()});input.value='';openLeadDetail(id);showToast('Komentar ditambahkan')}\nfunction toggleQaForm(fid){var f=document.getElementById(fid);if(!f)return;document.querySelectorAll('.qa-form.open').forEach(o=>{if(o!==f)o.classList.remove('open')});f.classList.toggle('open')}\nfunction saveActivity(id){\n  var type=document.getElementById('qaActType').value;\n  var date=document.getElementById('qaActDate').value;\n  var note=document.getElementById('qaActNote').value.trim();\n  if(!date){showToast('Tanggal wajib diisi');return}\n  var at=new Date(date+'T09:00:00').toISOString();\n  dbAdd('leadActivities',{id:genId('la'),leadId:id,type:'activity',actor:DB.currentUser?.id||'u1',text:'Dijadwalkan: '+type,detail:note||null,at:at});\n  // next action drives \"Butuh Follow-up\" metric + sorting\n  dbUpdate('leads',id,{nextAction:type+(note?' — '+note:''),nextActionAt:at});\n  openLeadDetail(id);renderLeads();showToast('Aktivitas dijadwalkan');\n}\nfunction saveVisit(id){\n  var l=dbFind('leads',id);if(!l)return;\n  var dt=document.getElementById('qaVisDate').value;\n  var loc=document.getElementById('qaVisLoc').value.trim();\n  var note=document.getElementById('qaVisNote').value.trim();\n  if(!dt){showToast('Tanggal & jam wajib diisi');return}\n  if(!loc){showToast('Lokasi wajib diisi');return}\n  var at=new Date(dt).toISOString();\n  dbAdd('visits',{id:genId('vs'),leadId:id,assignee:l.assignee,status:'on_plan',outcome:null,plannedAt:at,checkedInAt:null,closedAt:null,location:loc,note:note||null,approval:null});\n  dbAdd('leadActivities',{id:genId('la'),leadId:id,type:'visit',actor:DB.currentUser?.id||'u1',text:'Visit dijadwalkan',detail:loc,at:at});\n  openLeadDetail(id);renderLeads();showToast('Visit dibuat (menunggu kunjungan)');\n}\n\n// === TRANSITION GUARD ===\nfunction openTransition(id){\n  const l=dbFind('leads',id);if(!l)return;\n  const stages=getStages();const terminal=getTerminal();const fwdMap=getForwardMap();\n  const sObj=stageByKey(l.status);\n  const forwards=fwdMap[l.status]||[];\n  const curIdx=stageIndex(l.status);\n  const backward=stages.filter((s,i)=>i<curIdx&&!terminal.includes(s.key));\n  const isTerminal=terminal.includes(l.status);\n\n  let html=`<div class=\"tp-header\"><h3>Ubah Status</h3><span style=\"font-size:12px;padding:4px 10px;border-radius:6px;background:${sObj?.color||'#888'}22;color:${sObj?.color||'#888'}\">${sObj?.icon||'•'} ${sObj?.label||l.status}</span></div>`;\n\n  if(forwards.length){\n    html+=`<div class=\"tp-section\"><div class=\"tp-section-label\">Maju <span class=\"line\"></span></div>`;\n    forwards.forEach(sk=>{\n      const fs=stageByKey(sk);if(!fs)return;\n      const isTerm=terminal.includes(sk);\n      html+=`<div class=\"tp-option ${isTerm?'terminal':'forward'}\" onclick=\"${isTerm?`selectTerminal('${id}','${sk}')`:`doTransition('${id}','${sk}')`}\">\n        <div class=\"tp-opt-left\"><div class=\"tp-opt-dot\" style=\"background:${fs.color}\"></div><span class=\"tp-opt-name\">${fs.label}</span></div>\n        <span class=\"tp-opt-badge ${isTerm?'badge-terminal':'badge-next'}\">${isTerm?'🔒 Terminal':'→ Next'}</span>\n      </div>`;\n    });\n    html+=`</div>`;\n  }\n\n  if(backward.length){\n    html+=`<div class=\"tp-section\"><div class=\"tp-section-label\">Mundur <span class=\"line\"></span> 🔒 Butuh approval</div>`;\n    backward.forEach(bs=>{\n      html+=`<div class=\"tp-option locked\"><div class=\"tp-opt-left\"><div class=\"tp-opt-dot\" style=\"background:${bs.color}\"></div><span class=\"tp-opt-name\">${bs.label}</span></div><span class=\"tp-opt-badge badge-locked\">Supervisor</span></div>`;\n    });\n    html+=`</div>`;\n  }\n\n  html+=`<div id=\"tpConfirmArea\"></div>`;\n  document.getElementById('transitionPanel').innerHTML=html;\n  document.getElementById('transitionPopover').classList.add('open');\n}\n\nfunction selectTerminal(id,newStatus){\n  const reasonOpts=LOST_REASONS.map(r=>`<option>${r}</option>`).join('');\n  const label=stageByKey(newStatus)?.label||newStatus;\n  document.getElementById('tpConfirmArea').innerHTML=`<div class=\"tp-confirm\">\n    <div class=\"tp-confirm-title\">⚠️ Konfirmasi: ${label}</div>\n    <label>Alasan (wajib):</label>\n    <select id=\"tpReason\"><option value=\"\">Pilih alasan...</option>${reasonOpts}</select>\n    <textarea id=\"tpNote\" placeholder=\"Catatan tambahan (opsional)...\"></textarea>\n  </div>\n  <div class=\"tp-actions\"><button class=\"btn\" onclick=\"closeTransition()\">Batal</button><button class=\"btn danger\" onclick=\"confirmTerminal('${id}','${newStatus}')\">Konfirmasi ${label}</button></div>`;\n}\n\nfunction confirmTerminal(id,newStatus){\n  const reason=document.getElementById('tpReason').value;\n  if(!reason){showToast('Alasan wajib diisi');return}\n  const oldStatus=dbFind('leads',id)?.status;\n  const patch_={status:newStatus};\n  if(newStatus==='won'){patch_.wonReason=reason;patch_.wonAt=new Date().toISOString()}\n  if(newStatus==='lost'){patch_.lostReason=reason;patch_.lostAt=new Date().toISOString()}\n  dbUpdate('leads',id,patch_);\n  dbAdd('leadActivities',{id:genId('la'),leadId:id,type:'status',actor:DB.currentUser?.id||'u1',text:`Status: ${stageByKey(oldStatus)?.label||oldStatus} → ${stageByKey(newStatus)?.label||newStatus}`,detail:reason,at:new Date().toISOString()});\n  closeTransition();closeLeadDetail();renderLeads();showToast('Status diperbarui');\n}\n\nfunction doTransition(id,newStatus){\n  const oldStatus=dbFind('leads',id)?.status;\n  dbUpdate('leads',id,{status:newStatus});\n  dbAdd('leadActivities',{id:genId('la'),leadId:id,type:'status',actor:DB.currentUser?.id||'u1',text:`Status: ${stageByKey(oldStatus)?.label||oldStatus} → ${stageByKey(newStatus)?.label||newStatus}`,detail:null,at:new Date().toISOString()});\n  closeTransition();closeLeadDetail();renderLeads();showToast(`Status: ${stageByKey(newStatus)?.label||newStatus}`);\n}\n\nfunction closeTransition(){document.getElementById('transitionPopover').classList.remove('open')}\n\n// === CONTACT AUTOCOMPLETE ===\n// Satu datalist berisi tiap contact per field queryable (name/phone/email).\n// User ketik di field mana pun; onchange cari match lintas field lalu autofill.\n// ponytail: linear scan DB.contacts. Ratusan kontak masih instan; index kalau ribuan.\nfunction _esc(s){return String(s==null?'':s).replace(/\"/g,'&quot;').replace(/</g,'&lt;');}\nfunction contactDatalist(){\n  var opts=(DB.contacts||[]).map(function(c){\n    var extra=[c.phone,c.email].filter(Boolean).join(' · ');\n    // option per field agar ketik nomor/email tetap memunculkan kontak (label=nama)\n    var rows=[c.name,c.phone,c.email].filter(Boolean).map(function(v){\n      return '<option value=\"'+_esc(v)+'\" label=\"'+_esc(c.name+(extra?' — '+extra:''))+'\"></option>';\n    });\n    return rows.join('');\n  }).join('');\n  return '<datalist id=\"contactSuggest\">'+opts+'</datalist>';\n}\nfunction contactField(id,field,value){\n  return _cell('<input class=\"field-input\" list=\"contactSuggest\" type=\"text\" value=\"'+_esc(value)+'\" readonly'+\n    ' onchange=\"saveContactField(\\''+id+'\\',\\''+field+'\\',this.value)\" onblur=\"lockField(this)\">');\n}\n// cari kontak yang salah satu field-nya sama persis (case-insensitive) dengan query\nfunction findContact(q){\n  if(!q)return null;\n  var k=q.trim().toLowerCase();\n  return (DB.contacts||[]).find(function(c){\n    return [c.name,c.phone,c.email].some(function(v){return v&&String(v).toLowerCase()===k;});\n  })||null;\n}\nfunction saveContactField(id,field,value){\n  saveLeadField(id,field,value); // simpan apa adanya dulu (boleh kosong, boleh kontak baru)\n  var c=findContact(value);\n  if(c){\n    // autofill field lain yang masih kosong / berbeda + tautkan contactId\n    var patch={contactId:c.id};\n    if(c.name)patch.contact=c.name;\n    if(c.phone)patch.phone=c.phone;\n    if(c.email)patch.email=c.email;\n    dbUpdate('leads',id,patch);\n    openLeadDetail(id);\n    showToast('Kontak \"'+c.name+'\" ditautkan');\n  }else if(value&&value.trim()){\n    renderContactSuggest(id);\n  }\n}\n// tawarkan simpan kontak baru saat nama diisi tapi tak ada di collection\nfunction renderContactSuggest(id){\n  var box=document.getElementById('ldContactSuggest');\n  if(!box)return;\n  var l=dbFind('leads',id);\n  if(!l||l.contactId||!l.contact){box.innerHTML='';return;}\n  if(findContact(l.contact)){box.innerHTML='';return;}\n  box.innerHTML='<div class=\"contact-new\">Kontak baru — '+\n    '<button class=\"link-btn\" onclick=\"saveNewContact(\\''+id+'\\')\">Simpan ke daftar kontak</button></div>';\n}\nfunction saveNewContact(id){\n  var l=dbFind('leads',id);\n  if(!l||!l.contact)return;\n  var c={id:genId('c'),name:l.contact,phone:l.phone||null,email:l.email||null,channel:'manual',tags:[],lastActive:new Date().toISOString()};\n  dbAdd('contacts',c);\n  dbUpdate('leads',id,{contactId:c.id});\n  openLeadDetail(id);\n  showToast('Kontak \"'+c.name+'\" disimpan ke daftar');\n}\n\n// === INLINE EDIT ===\nfunction saveLeadField(id,field,value){\n  if(field==='value')value=+value||0;\n  if(value==='')value=null;\n  var patch_={};\n  patch_[field]=value;\n  dbUpdate('leads',id,patch_);\n  dbAdd('leadActivities',{id:genId('la'),leadId:id,type:'activity',actor:DB.currentUser?.id||'u1',text:`${field} diperbarui`,detail:String(value).substring(0,80),at:new Date().toISOString()});\n  showToast('Tersimpan');\n  // Refresh board/table behind modal\n  renderLeads();\n}\n\n// === VISIT MODAL (inject visits fragment, run its script in-page) ===\nfunction openVisitModal(){\n  var body=document.getElementById('visitModalBody');\n  var frag=(window.__PAGES&&window.__PAGES['pages/visits.html'])||'<div style=\"padding:40px\">Bundle visits.html hilang — jalankan build.py</div>';\n  body.innerHTML=frag;\n  // run inline scripts (visits.html defines renderVisits + handlers on window)\n  body.querySelectorAll('script').forEach(function(s){\n    var ns=document.createElement('script');ns.textContent=s.textContent;document.body.appendChild(ns);s.remove();\n  });\n  document.getElementById('visitModal').classList.add('open');\n}\nfunction closeVisitModal(){\n  document.getElementById('visitModal').classList.remove('open');\n  renderLeads(); // refresh counter after approve/reject\n}\n\n// === CREATE LEAD (form + validasi) ===\nvar CL_FIELDS=['clCompany','clContact','clPhone','clEmail','clValue','clAssignee','clSource','clSegment','clStatus'];\nvar clVariant='a';\n// ponytail: create hanya boleh stage non-terminal — won/lost butuh reason+approval, jalur itu di detail modal (confirmTerminal). getTerminal() sudah ada.\nfunction clStages(){var t=getTerminal();return getStages().filter(s=>!t.includes(s.key));}\nfunction clFirstStage(){return clStages()[0]?.key||'new';}\n// tiga varian tampilan form create. field id sama di ketiganya → save/validasi tak berubah.\nfunction clSelectsHTML(){\n  var seg='<option value=\"\">— Tanpa segment —</option>'+getSegments().map(s=>'<option value=\"'+_esc(s)+'\">'+_esc(s)+'</option>').join('');\n  var asg=DB.agents.map(a=>'<option value=\"'+a.id+'\"'+(a.id===(DB.currentUser?.id)?' selected':'')+'>'+_esc(a.name)+'</option>').join('');\n  var src='<option>WhatsApp</option><option>Widget</option><option>Broadcast</option><option>Referral</option>';\n  var sts=clStages().map(s=>'<option value=\"'+s.key+'\">'+_esc(s.icon+' '+s.label)+'</option>').join('');\n  return {seg:seg,asg:asg,src:src,sts:sts};\n}\nfunction clBodyHTML(v){\n  var o=clSelectsHTML();\n  var contact='<input id=\"clContact\" class=\"cl-in\" list=\"contactSuggest\" type=\"text\" placeholder=\"Ketik nama / telepon / email\" oninput=\"clFillContact()\">';\n  var phone='<input id=\"clPhone\" class=\"cl-in\" type=\"text\" placeholder=\"+62…\">';\n  var email='<input id=\"clEmail\" class=\"cl-in\" type=\"email\" placeholder=\"email@…\">';\n  var val='<input id=\"clValue\" class=\"cl-in\" type=\"number\" min=\"0\" placeholder=\"0\">';\n  var asg='<select id=\"clAssignee\" class=\"cl-in\">'+o.asg+'</select>';\n  var src='<select id=\"clSource\" class=\"cl-in\">'+o.src+'</select>';\n  var seg='<select id=\"clSegment\" class=\"cl-in\">'+o.seg+'</select>';\n  var sts='<select id=\"clStatus\" class=\"cl-in\">'+o.sts+'</select>';\n  var actions='<div id=\"clError\" class=\"cl-error hide\"></div><div class=\"cl-actions\"><button class=\"btn\" onclick=\"closeCreateLead()\">Batal</button><button class=\"btn primary\" onclick=\"saveCreateLead()\">Simpan Prospek</button></div>';\n  var host='<div id=\"clDatalistHost\"></div>';\n  if(v==='a'){ // detail-style: summary card + section akordeon\n    return '<div style=\"padding:20px\">'+\n      '<div class=\"ld-summary\"><div class=\"ld-summary-top\"><div style=\"flex:1\">'+\n      '<input id=\"clCompany\" class=\"cl-title\" type=\"text\" placeholder=\"Judul Lead (perusahaan / perorangan) *\" oninput=\"clError(\\'\\')\">'+\n      '<div class=\"ld-summary-sub\">Prospek baru · isi detail di bawah</div></div></div>'+\n      '<div class=\"cl-stepper-wrap\" id=\"clStepperWrap\"></div>'+\n      '<input type=\"hidden\" id=\"clStatus\">'+\n      '<div class=\"ld-summary-grid\">'+\n      '<div class=\"ld-summary-item\"><div class=\"lbl\">Nilai</div><div class=\"val green\">'+val+'</div></div>'+\n      '<div class=\"ld-summary-item\"><div class=\"lbl\">Assignee</div><div class=\"val\">'+asg+'</div></div>'+\n      '<div class=\"ld-summary-item\"><div class=\"lbl\">Sumber</div><div class=\"val\">'+src+'</div></div>'+\n      '<div class=\"ld-summary-item\"><div class=\"lbl\">Segment</div><div class=\"val\">'+seg+'</div></div>'+\n      '</div></div>'+\n      '<div class=\"ld-section\"><div class=\"ld-section-header\">👤 Informasi Kontak</div><div class=\"ld-section-body\">'+\n      '<div class=\"field-row\"><span class=\"lbl\">Nama PIC</span>'+contact+'</div>'+\n      '<div class=\"field-row\"><span class=\"lbl\">Telepon</span>'+phone+'</div>'+\n      '<div class=\"field-row\"><span class=\"lbl\">Email</span>'+email+'</div>'+host+'</div></div>'+actions+'</div>';\n  }\n  if(v==='b'){ // ringkas: satu kolom label-atas, tanpa akordeon/grid\n    return '<div style=\"padding:20px;display:flex;flex-direction:column;gap:12px\">'+\n      '<label class=\"cl-lbl\">Judul Lead *<input id=\"clCompany\" class=\"cl-in\" type=\"text\" placeholder=\"Perusahaan / perorangan\" oninput=\"clError(\\'\\')\"></label>'+\n      '<label class=\"cl-lbl\">Status'+sts+'</label>'+\n      '<label class=\"cl-lbl\">Nama PIC'+contact+'</label>'+\n      '<label class=\"cl-lbl\">Telepon'+phone+'</label>'+\n      '<label class=\"cl-lbl\">Email'+email+'</label>'+\n      '<label class=\"cl-lbl\">Nilai'+val+'</label>'+\n      '<label class=\"cl-lbl\">Assignee'+asg+'</label>'+\n      '<label class=\"cl-lbl\">Sumber'+src+'</label>'+\n      '<label class=\"cl-lbl\">Segment'+seg+'</label>'+host+actions+'</div>';\n  }\n  // v==='c' — form sederhana padat: 2 kolom\n  return '<div style=\"padding:20px;display:flex;flex-direction:column;gap:8px\">'+\n    '<label class=\"cl-lbl\">Judul Lead *<input id=\"clCompany\" class=\"cl-in\" type=\"text\" placeholder=\"Perusahaan / perorangan\" oninput=\"clError(\\'\\')\"></label>'+\n    '<label class=\"cl-lbl\">Nama PIC'+contact+'</label>'+\n    '<div class=\"cl-2col\"><label class=\"cl-lbl\">Telepon'+phone+'</label><label class=\"cl-lbl\">Email'+email+'</label></div>'+\n    '<div class=\"cl-2col\"><label class=\"cl-lbl\">Nilai'+val+'</label><label class=\"cl-lbl\">Sumber'+src+'</label></div>'+\n    '<div class=\"cl-2col\"><label class=\"cl-lbl\">Assignee'+asg+'</label><label class=\"cl-lbl\">Segment'+seg+'</label></div>'+\n    '<div class=\"cl-2col\"><label class=\"cl-lbl\">Status'+sts+'</label><span style=\"flex:1\"></span></div>'+host+actions+'</div>';\n}\nfunction clReadFields(){var d={};CL_FIELDS.forEach(id=>{var e=document.getElementById(id);if(e)d[id]=e.value;});return d;}\nfunction clWriteFields(d){CL_FIELDS.forEach(id=>{var e=document.getElementById(id);if(e&&d[id]!=null)e.value=d[id];});}\n// stepper klik (varian A): fill semua segmen sampai stage yang diklik, mirip pipeline detail\nfunction clRenderStepper(){\n  var wrap=document.getElementById('clStepperWrap');if(!wrap)return;\n  var stages=clStages(),cur=document.getElementById('clStatus').value,ci=stages.findIndex(s=>s.key===cur);\n  if(ci<0)ci=0;\n  wrap.innerHTML='<div class=\"ld-pipeline-track\">'+stages.map((s,i)=>'<div class=\"cl-step'+(i<ci?' done':i===ci?' current':'')+'\" onclick=\"clSetStatus(\\''+s.key+'\\')\"></div>').join('')+'</div>'+\n    '<div class=\"ld-pipeline-labels\">'+stages.map((s,i)=>'<span'+(i===ci?' class=\"active\"':'')+'>'+_esc(s.label)+'</span>').join('')+'</div>'+\n    '<div class=\"cl-step-hint\">Won / Lost diset setelah lead dibuat (butuh alasan).</div>';\n}\nfunction clSetStatus(key){if(getTerminal().includes(key))return;document.getElementById('clStatus').value=key;clRenderStepper();}\nfunction clRenderBody(keep){\n  document.getElementById('clBody').innerHTML=clBodyHTML(clVariant);\n  var host=document.getElementById('clDatalistHost');if(host)host.innerHTML=contactDatalist();\n  var so=document.getElementById('clSource');if(so&&!(keep&&keep.clSource))so.value='WhatsApp';\n  var st=document.getElementById('clStatus');if(st&&!(keep&&keep.clStatus))st.value=clFirstStage();\n  if(keep)clWriteFields(keep);\n  clRenderStepper();\n  document.querySelectorAll('#clVariant button').forEach(b=>b.classList.toggle('active',b.dataset.v===clVariant));\n  clError('');\n}\nfunction setCreateVariant(v){var keep=clReadFields();clVariant=v;clRenderBody(keep);}\nfunction openCreateLead(){\n  clRenderBody(null);\n  document.getElementById('createLeadModal').classList.add('open');\n  document.getElementById('clCompany').focus();\n}\nfunction closeCreateLead(){document.getElementById('createLeadModal').classList.remove('open')}\nfunction clError(msg){var e=document.getElementById('clError');if(!e)return;e.textContent=msg;e.classList.toggle('hide',!msg);}\n// autofill telepon/email saat nama kontak cocok kontak existing\nfunction clFillContact(){\n  var c=findContact(document.getElementById('clContact').value);\n  if(!c)return;\n  document.getElementById('clContact').value=c.name||'';\n  if(c.phone)document.getElementById('clPhone').value=c.phone;\n  if(c.email)document.getElementById('clEmail').value=c.email;\n}\nfunction saveCreateLead(){\n  var company=document.getElementById('clCompany').value.trim();\n  if(company.length<3){clError('Judul Lead minimal 3 karakter');document.getElementById('clCompany').focus();return;}\n  var contact=document.getElementById('clContact').value.trim()||null;\n  var phone=document.getElementById('clPhone').value.trim()||null;\n  var email=document.getElementById('clEmail').value.trim()||null;\n  if(email&&!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email)){clError('Format email tidak valid');document.getElementById('clEmail').focus();return;}\n  var value=Math.max(0,+document.getElementById('clValue').value||0);\n  var source=document.getElementById('clSource').value;\n  var segment=document.getElementById('clSegment').value||null;\n  var agentId=document.getElementById('clAssignee').value||DB.currentUser?.id||'u1';\n  var status=document.getElementById('clStatus').value;\n  if(!status||getTerminal().includes(status))status=clFirstStage(); // guard: lead baru tak boleh lahir terminal (won/lost butuh reason di detail)\n  var c=contact?findContact(contact):null; // tautkan bila kontak sudah ada\n  var newId=genId('ld');\n  dbAdd('leads',{id:newId,company:company,contact:contact,phone:phone,email:email,contactId:c?c.id:null,value:value,source:source,description:'',assignee:agentId,teamId:'t2',tags:[],segment:segment,status:status,nextAction:null,nextActionAt:null,createdAt:new Date().toISOString()});\n  dbAdd('leadActivities',{id:genId('la'),leadId:newId,type:'created',actor:'system',text:'Lead dibuat',detail:'Assignee: '+(DB.agents.find(a=>a.id===agentId)?.name||'-'),at:new Date().toISOString()});\n  closeCreateLead();\n  renderLeads();\n  openLeadDetail(newId);\n  showToast('Prospek \"'+company+'\" dibuat');\n}\n\n// === DELETE LEAD (spv + admin) ===\n// ponytail: effective role dari class #app (role switcher), sama seperti gating lain.\nfunction currentRole(){return (document.getElementById('app')?.className.match(/role-(\\w+)/)||[])[1]||'agent';}\nfunction canDelete(){return currentRole()==='admin'||currentRole()==='spv';}\nfunction deleteLead(id){\n  if(!canDelete()){showToast('Hanya Supervisor/Admin yang bisa hapus prospek');return;}\n  var l=dbFind('leads',id);if(!l)return;\n  if(!confirm('Hapus prospek \"'+l.company+'\"? Tindakan ini tidak bisa dibatalkan.'))return;\n  dbRemove('leads',id);\n  (DB.leadActivities||[]).filter(a=>a.leadId===id).forEach(a=>dbRemove('leadActivities',a.id));\n  (DB.visits||[]).filter(v=>v.leadId===id).forEach(v=>dbRemove('visits',v.id));\n  closeLeadDetail();\n  renderLeads();\n  showToast('Prospek \"'+l.company+'\" dihapus');\n}\n\n// Init\nrenderLeads();\n</script>\n";
